/// Sect printed on the card (rulebook "Vampiric Sects").
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Sect {
    Camarilla,
    Anarch,
    Independent,
    Sabbat,
}

/// A title, printed or granted by a card. Prince, Baron and Archbishop of the
/// same city contest each other; each clan's Justicar and Inner Circle
/// member is unique; primogen is not unique. `Independent`: a unique
/// Independent title a card names, worth its votes (Saulot's Guiding
/// Wisdom); no V5 vampire prints one.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Title {
    None,
    Primogen,
    Prince(&'static str),
    Baron(&'static str),
    Justicar(&'static str),
    InnerCircle(&'static str),
    Archbishop(&'static str),
    /// Sabbat titles that are not unique (bishop 1 vote, cardinal 3; a
    /// priscus votes in the prisci block) and the unique regent (4).
    Bishop,
    Cardinal,
    Priscus,
    Regent,
    /// "n votes (titled)" printed on an Independent vampire (Arishat,
    /// Scout Youngwood): a title worth n votes, not unique.
    Votes(u8),
    Independent {
        name: &'static str,
        votes: u8,
    },
}

